<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount,nextTick,watch} from 'vue'
import {dashboard,usable} from '../store'
import {run} from '../composables/useDashboard'
import {player,progress,seekable,beginSeek,previewSeek,commitSeek,cancelSeek,usePlayback} from '../composables/usePlayback'
import {lyrics,toggleLyrics,centerLine} from '../composables/useLyrics'
import {useLibrary} from '../composables/useLibrary'
import {duration,safeURL,songLinkURL} from '../composables/useTrack'
import {t} from '../composables/useLocale'
import {useSpotifyLink} from '../composables/useSpotifyLink'
import TrackArt from './TrackArt.vue'
usePlayback();const library=useLibrary(),dock=ref<HTMLElement|null>(null)
const track=computed(()=>dashboard.snapshot?.current),state=computed(()=>dashboard.snapshot)
const active=computed(()=>usable.value&&!!track.value&&['playing','paused'].includes(state.value?.status||''))
const position=computed(()=>player.preview??progress.value)
const repeatLabel=computed(()=>t(state.value?.repeat==='song'?'m0115':state.value?.repeat==='all'?'m0116':'m0114'))
const source=computed(()=>songLinkURL(track.value?.url))
const {url:spotify,loading:spotifyLoading}=useSpotifyLink()
let observer:ResizeObserver|undefined
function measure(){if(dock.value)document.documentElement.style.setProperty('--dock-player-height',Math.ceil(dock.value.getBoundingClientRect().height)+'px')}
function syncIcon(){dock.value?.querySelector('#toggle')?.setAttribute('data-playing',String(state.value?.status==='playing'))}
watch(()=>state.value?.status,syncIcon,{flush:'post'})
async function changeVolume(){await run('volume',{volume:player.volume});if(dashboard.snapshot?.volume!==null&&dashboard.snapshot?.volume!==undefined)player.volume=dashboard.snapshot.volume}
async function choices(){player.choices=!player.choices;if(player.choices){lyrics.menu=false;await nextTick();document.getElementById('source-link')?.focus()}else void centerLine()}
function outside(event:Event){if(!(event.target as HTMLElement)?.closest?.('.bar-copy')){player.choices=false;void centerLine()}}
function key(event:KeyboardEvent){if(event.key==='Escape')player.choices=false}
function seekKey(event:KeyboardEvent){if(event.key==='Escape'){cancelSeek();return}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(event.key))beginSeek('keyboard')}
function releaseKey(event:KeyboardEvent){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(event.key))void commitSeek()}
function blurSeek(){if(player.kind==='keyboard'&&player.preview!==null)void commitSeek();else cancelSeek()}
onMounted(()=>{measure();syncIcon();observer=new ResizeObserver(measure);if(dock.value)observer.observe(dock.value);document.addEventListener('pointerdown',outside);document.addEventListener('focusin',outside);document.addEventListener('keydown',key)})
onBeforeUnmount(()=>{observer?.disconnect();document.removeEventListener('pointerdown',outside);document.removeEventListener('focusin',outside);document.removeEventListener('keydown',key)})
</script>
<template><section id="playback-bar" ref="dock" class="playback-bar" :aria-label="t('m0328')"><div class="bar-track"><TrackArt :track="track" class="mini-art" image-id="bar-cover"/><div class="bar-copy"><button id="bar-title" type="button" :disabled="!track" :aria-expanded="player.choices" aria-controls="song-choices" aria-haspopup="true" @click="choices">{{ track?.title||t('m0110') }}</button><small id="bar-status">{{ track ? (state?.status==='preparing' ? t('player.preparingNext') : t(state?.status==='playing'?'m0040':state?.status==='paused'?'m0041':'m0111')+t('m0112')+(track.requester?.name||t('m0045'))) : t('m0113') }}</small><div id="song-choices" class="song-choices" role="group" :aria-label="t('m0329')" :hidden="!player.choices"><a id="source-link" :href="source||undefined" target="_blank" rel="noopener noreferrer">{{ t(source.includes('youtube.com')?'m0106':'m0107') }}</a><a id="song-spotify" :href="spotify||undefined" :hidden="!track" :aria-disabled="spotifyLoading||!spotify" :class="{'is-loading':spotifyLoading}" @click="(spotifyLoading||!spotify)&&$event.preventDefault()" target="_blank" rel="noopener noreferrer">{{ t('m0330') }}</a></div></div><button id="favorite" class="player-control" type="button" :disabled="!usable||!safeURL(track?.url)||library.busy.value" :aria-label="t(library.isFavorite()?'m0200':'m0201')" :aria-pressed="library.isFavorite()" @click="library.toggleFavorite()">{{ library.isFavorite()?'♥':'♡' }}</button></div><div class="bar-center"><div id="player-transport" class="transport"><button id="toggle" class="primary player-control" :disabled="!active||state?.capabilities?.[state.status==='playing'?'pause':'resume']!==true" :aria-label="t('m0331')" @click="run(state?.status==='playing'?'pause':'resume')"><svg v-if="state?.status==='playing'" class="transport-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="6" y="4.5" width="4.5" height="15" rx="1.1" fill="currentColor" stroke="none"/><rect x="13.5" y="4.5" width="4.5" height="15" rx="1.1" fill="currentColor" stroke="none"/></svg><svg v-else class="transport-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4.5a1 1 0 0 1 1.5-.86l11 7.5a1 1 0 0 1 0 1.72l-11 7.5A1 1 0 0 1 7 19.5z" fill="currentColor" stroke="none"/></svg><span class="sr-only">{{ t(state?.status==='playing'?'m0108':'m0109') }}</span></button><button id="skip" class="player-control" :disabled="!active||state?.capabilities?.skip!==true" :aria-label="t('m0332')" @click="run('skip')"><svg class="transport-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5.5a1 1 0 0 1 1.5-.86l9 6.5a1 1 0 0 1 0 1.72l-9 6.5A1 1 0 0 1 4 18.5z" fill="currentColor" stroke="none"/><rect x="17" y="4.5" width="3" height="15" rx="1" fill="currentColor" stroke="none"/></svg><span class="sr-only">{{ t('m0333') }}</span></button><button id="repeat" class="repeat-control player-control" :disabled="!usable||state?.status==='disconnected'" :aria-label="t('m0117')+t(state?.repeat==='off'?'m0118':state?.repeat==='song'?'m0115':'m0119')" :aria-pressed="state?.repeat!=='off'" :value="state?.repeat" @click="run('repeat',{mode:state?.repeat==='off'?'song':state?.repeat==='song'?'all':'off'})"><svg class="transport-icon" viewBox="0 0 24 24" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3l4 4-4 4M3 11V9a2 2 0 0 1 2-2h16"/><path d="M7 21l-4-4 4-4M21 13v2a2 2 0 0 1-2 2H3"/></g></svg><span v-if="state?.repeat==='song'" class="transport-repeat-one" aria-hidden="true">1</span><span class="sr-only">{{ repeatLabel }}</span></button></div><div class="progress-row"><span id="elapsed">{{ duration(position) }}</span><input id="progress" type="range" min="0" :max="track?.duration||1" step="1" :value="position" :disabled="!seekable" :aria-label="t('m0335')" :aria-valuetext="duration(position)+t('m0130')+duration(track?.duration)" @pointerdown="beginSeek('pointer',$event)" @input="previewSeek" @change="player.kind==='assistive'&&commitSeek()" @keydown="seekKey" @keyup="releaseKey" @blur="blurSeek"><span id="duration">{{ track?.duration?duration(track.duration):t('m0085') }}</span></div></div><p class="sr-only seek-hint">{{ t('m0336') }}</p><div class="bar-right"><button id="lyrics-toggle" class="player-control" type="button" :hidden="state?.lyrics_available===false" :disabled="!usable||!track||state?.lyrics_available===false" :aria-expanded="lyrics.open" aria-controls="lyrics-panel" @click="player.choices=false;toggleLyrics()">{{ t('m0141') }}</button><div class="volume-row"><label for="volume" class="sr-only">{{ t('m0337') }}</label><input id="volume" v-model.number="player.volume" type="range" min="1" max="100" :disabled="!usable||state?.volume===null||state?.status==='disconnected'" :aria-label="t('m0337')" @change="changeVolume"><output id="volume-label" for="volume">{{ player.volume }}%</output></div></div></section></template>
